const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.grid}</svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>Number(v).toLocaleString('ru-RU',{maximumFractionDigits:1});
const date=(v,withDate=false)=>new Date(v).toLocaleString('ru-RU',{...(withDate?{day:'numeric',month:'short'}:{}),hour:'2-digit',minute:'2-digit'});
const relative=v=>{const m=Math.max(0,Math.floor((Date.now()-new Date(v))/60000));return m<1?'только что':m<60?`${m} мин. назад`:m<1440?`${Math.floor(m/60)} ч. назад`:date(v,true);};
