async function api(path,options={}) {
  const response=await fetch(path,{...options,headers:{'content-type':'application/json',...(options.method&&options.method!=='GET'?{'idempotency-key':options.key||key()}:{}),...options.headers},...(options.body?{body:JSON.stringify(options.body)}:{})});
  let body;try{body=await response.json();}catch{throw new Error('Сервер вернул непонятный ответ. Повторите запрос.');}
  if(!response.ok){const error=new Error(body.error||'Не удалось выполнить запрос.');error.code=body.code;error.status=response.status;throw error;}
  return body;
}
async function load(){data=await api('/api/bootstrap?'+params());department=data.filters.department;product=data.filters.product;render();}
async function init(){
  try{await load();}catch(error){
    if(error.status===401){try{await api('/api/session',{method:'POST',body:{role:['executive','maxim','sergey','operator','support_staff','growth_staff'].includes(localStorage.getItem('contour-role'))?localStorage.getItem('contour-role'):'executive'}});await load();return;}catch(e){error=e;}}
    document.querySelector('#app').innerHTML=`<div class="boot">${icon('alert')}<h2>Не удалось загрузить контур</h2><p>${esc(error.message)}</p><button class="btn btn-primary" data-action="reload">Повторить</button></div>`;
  }
}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'alert':'check')+`<span>${esc(message)}</span>`;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),6500);}
